new_string:
if self.openapi_version.major < 3:
    ret.update(prop)
else:
    # Promote certain properties from schema to parameter level
    for param_level_prop in ["description", "deprecated"]:
        if param_level_prop in prop:
            ret[param_level_prop] = prop.pop(param_level_prop)
    ret["schema"] = prop
